pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_post * norm_post);

    // Non-linear coupling with stream progress: later in stream, penalize waste more strongly
    score += 20.0 * norm_post.powi(3) * (0.5 + progress);

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (ns - pr).max(0.0) / cap;
        score += 15.0 * waste * waste * (1.0 - progress);
    }

    // Last-chance bonus: only bin that fits -> reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - norm_post);
    }

    // Slight preference to keep bins balanced relative to mean residual
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_residual && bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain residue classes.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual divisible by 5 or 10 -> "reusable" residual class.
    // Class 2: small odd residues -> likely dead space, penalize.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 18.0;
    } else if post_residual % 5 == 0 {
        score -= 9.0;
    } else if post_residual % 2 == 1 && post_residual < 10 {
        score += 14.0;
    }

    // Harmonic coupling: post_residual + next_item_size forms a perfect class (item fills bin next step)
    if next_item_size > 0 {
        let combo = post_residual + next_item_size;
        if combo == bin_capacity {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here: reward proportionally
            let r = post_residual as f64 / next_item_size as f64;
            score -= 6.0 * r.min(3.0);
        } else {
            // next item won't fit: mild penalty scaled by how close it was
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tight fits: relative fill fraction of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill;

    // Penalize bins far from mean residual (fragmentation spread).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Early in stream: encourage consolidation into few bins.
    let progress = step_index as f64 / total_items as f64;
    score += 4.0 * progress * (open_bins_count as f64).sqrt();

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size > bin_capacity / 2) as f64;
        score -= 20.0 * pressure * (1.0 + big_item);
        score += 30.0 * (1.0 - pressure) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals too small to hold even the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Small-but-usable gaps are risky if they can't fit the next item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (low post residual relative to capacity).
    score -= 30.0 * (1.0 - post / cap);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // If this bin is the only one that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

