pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Prefer tight fits: reward small post_residual relative to bin size.
    score -= 12.0 * (1.0 - post / cap);

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let next_fit_quality = 1.0 - ((post - nxt) / cap);
            score -= 10.0 * next_fit_quality;
        } else {
            // Next item won't fit here: penalize leaving space that is too small to be useful.
            let waste = post / cap;
            score += 6.0 * waste * waste;
        }
    }

    // Penalize deviation of resulting residual from the mean residual (keeps bins homogeneous).
    score += 0.5 * (post - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild encouragement to fill existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post / cap);

    // New empty bin: penalize slightly so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: post-placement residual (lower is better = tighter fit)
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space < 10 is precious)
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Penalize leaving awkward residuals that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // tiny slivers are dead space
    }
    // Residuals in [10, 30] are reusable by typical items; reward them mildly
    if post_residual >= 10 && post_residual <= 30 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - slack / 60.0)).max(0.0);
        } else {
            // next item won't fit here; slight penalty for consuming space it needs
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins fit poorly (large post_residual) or few fitting bins exist.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; make it competitive with mediocre fits
        score = 55.0 + (item_size as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        } else if fitting_bins_count == 1 {
            score += 15.0; // discourage abandoning the last fitting bin
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global pressure: many open bins with high mean residual -> encourage
    // filling existing bins rather than fragmenting further
    if bin_residual != bin_capacity {
        let fill_bonus = (mean_residual - post_residual as f64).max(0.0) * 0.3;
        score -= fill_bonus;
        score += (open_bins_count as f64).sqrt() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping in progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: penalize large residuals more as stream progresses
    score += 12.0 * progress * norm_pr * norm_pr * cap.sqrt();

    // Reward tight fits (small post_residual) with a smooth quadratic bonus
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (item_size as f64) * 0.6;

    // Last-chance bin: smooth exponential reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: penalize if post_residual can't fit next item, smoothly
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let nx = next_item_size as f64 / cap;
        score += (1.0 - fits_next) * (6.0 + 10.0 * progress) * nx;
        score -= fits_next * 4.0 * nx * (1.0 - progress);
    }

    // Mean residual deviation: smooth quadratic penalty for deviating from the mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap * (0.5 + 0.5 * progress);

    // New-bin candidate: keep it competitive early, discourage late fragmentation
    if bin_residual == bin_capacity {
        score = 18.0 - 14.0 * progress + 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: coarse integer division into
    // capacity-fraction buckets. Buckets: [0..9], [10..19], [20..34],
    // [35..49], [50..74], [75..100]. Small buckets are good fits.
    let class = match post_residual {
        0..=9 => 0u32,
        10..=19 => 1,
        20..=34 => 2,
        35..=49 => 3,
        50..=74 => 4,
        _ => 5,
    };
    // Reward finer classes (smaller post_residual bucket).
    score -= (5 - class) as f64 * 3.0;

    // Perfect fit bonus: residual fully consumed.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: post_residual too small to ever hold the
    // smallest plausible item (harmonic class 0 is only good if it's 0).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual
    // exactly or nearly (harmonic chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 10.0 - gap as f64 * 0.5;
            } else {
                score += gap as f64 * 0.1;
            }
        } else {
            // Next item won't fit here: mild penalty scaled by overshoot.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin (residual == capacity)
    // should only win when fits elsewhere are poor. Penalize it
    // moderately, but less when many bins are already open (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 8.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the
    // mean, it's already a "junk" bin; placing here consolidates waste.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.15;
    }

    // Prefer filling nearly-full bins tighter as the stream progresses.
    let fill_ratio = (bin_capacity - post_residual) as f64 / cap;
    score -= fill_ratio * fill_ratio * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // minimum item size are pure waste; penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        score += 1000.0; // tiny dead sliver
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    }

    // Penalize gaps below the next item's size if next item can't use them:
    // they will likely become dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.9 * (next_item_size - post_residual) as f64;
    }

    // Reward when the next item exactly fits the remaining space (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is good; encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress) * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make the empty bin moderately attractive so it wins
    // only when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 5.0; // extra caution when alternatives exist
        }
    }

    // Slight pull toward bins whose residual matches current mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> chain exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong reward when next item fits exactly after this placement.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward closeness of the match.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item would not fit here: penalize proportionally to wasted gap.
            score += 10.0 + diff * 0.5;
        }
        // Bonus for small leftover after chaining both items.
        score -= 0.3 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;
    }

    // Penalize creating tiny unusable residuals (dead space below min item size 1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (good packing density).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, allow opening new bins more freely; later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins are open.
        score += 5.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Slight preference for filling bins with larger residual usage.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that nothing in the plausible size range can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // awkward gap
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement (chaining good fits).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0; // perfect chain
        } else if gap > 0 && (gap as u32) < 10 {
            score -= 15.0; // next item fits leaving small residue
        } else if gap < 0 && (-gap) < 10 {
            score += 10.0; // next item barely misses; near-miss penalty
        }
        // Reward leaving room proportional to next item size.
        if post_residual as f64 >= next_item_size as f64 {
            score -= 5.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation
    // into existing bins rather than opening new ones.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += crowding * 0.8;

    // Deviation from mean residual: prefer bins whose residual is already
    // below average (filling the "dirtiest" bins first keeps clean bins flexible).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins tidy); late in the stream, squeeze into anything available.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bonus = (1.0 - progress) * 15.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus adaptive bonus.
        score += 30.0 - new_bin_bonus;
        // If item is large relative to capacity, opening fresh is cheaper.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Small item into large residual: mild penalty (wasteful pairing).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio < 0.3 {
        score += 10.0 * (0.3 - fill_ratio) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = norm_pr * norm_pr * cap + 0.5 * norm_pr * cap;

    // Smooth progress coupling: later in stream, penalize residual more strongly
    let progress_gain = 1.0 + 2.0 * progress * progress + progress;
    score *= progress_gain;

    // Non-linear interaction between post_residual and mean residual:
    // penalize bins whose residual deviates from the pack mean (fragmentation)
    let mean_norm = mean_residual / cap;
    let dev = norm_pr - mean_norm;
    score += cap * (dev * dev) * (0.3 + 0.7 * progress);

    // Reward using nearly-full bins: subtract smooth function of fill ratio
    let fill = (bin_residual as f64) / cap;
    score -= cap * fill * fill * (0.4 + 0.6 * progress);

    // Last-chance bin bonus (smooth, scaled by how tight the fit is)
    if fitting_bins_count == 1 {
        score -= cap * (1.0 - norm_pr) * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: if next item fits in the post residual, reward;
    // smooth interaction with progress
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nxt = next_item_size as f64 / cap;
        score -= cap * nxt * (1.0 - nxt) * (0.6 + 0.8 * progress);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty proportional to wasted pairing potential
        let nxt = next_item_size as f64 / cap;
        score += cap * nxt * norm_pr * (0.2 + 0.4 * progress);
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, decaying as stream progresses
        let mut nb = cap * (1.2 - 0.5 * progress);
        // cheaper to open a new bin when many open bins already exist
        nb -= (open_bins_count as f64).ln().max(0.0) * cap * 0.05;
        // expensive if current bin would leave a large dead space
        nb -= 0.3 * norm_pr * cap;
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1
    let class = (frac * 8.0).floor() as i32; // 8 harmonic octaves of residual

    // Perfect fills are heavily rewarded (post_residual 0 or tiny slivers).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize "awkward" residual classes: residuals in (10,20] and (30,40]
    // are dead zones for typical item sizes (items >= 10 rarely fit).
    match class {
        0 => score -= 15.0,                       // [0,12.5) tiny: good
        1 => score += 12.0,                       // [12.5,25): dead zone
        2 => score -= 5.0,                        // [25,37.5): usable
        3 => score += 8.0,                        // [37.5,50): semi-dead
        4 => score -= 2.0,                        // [50,62.5): fine
        5 => score += 3.0,
        6 => score -= 1.0,
        _ => score += 0.0,                        // near-empty bin
    }

    // Lookahead coupling: does next_item_size exactly fill the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 25.0; // near-perfect chain
            } else {
                score -= (10.0 - slack.min(10) as f64).max(0.0);
            }
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so that
    // decent fits into open bins win, but a hopeless fit opens a new bin.
    if bin_residual == bin_capacity {
        score = cap * 0.55; // 55.0 baseline for opening a fresh bin
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing big items together is fine
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Mild pressure against bin proliferation late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln() * (1.0 + progress) * 0.5;

    // Reward filling bins tighter than the current mean residual.
    score -= (mean_residual - pr).max(-20.0).min(20.0) * 0.3;

    // Modulo-10 harmonic bonus: residuals that are multiples of 10 align
    // with the item-size grid (min item 10), improving future fits.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically small gaps) are heavily penalized.
    let dead_threshold = 10u32.min(bin_capacity / 4);
    if post_residual > 0 && post_residual < dead_threshold {
        let severity = (dead_threshold - post_residual) as f64 / dead_threshold as f64;
        score += 40.0 * severity + 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }
    // Penalize gaps that cannot fit the known next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.25 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0; // leaves room for lookahead
    }

    // Tight fit reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; make new bins less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or no good fits exist; otherwise penalize so consolidation wins.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight tie-break toward bins whose residual is above average (keeps
    // small-residual bins for small items).
    if (bin_residual as f64) < mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (best fit)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: strongly reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits perfectly -> big reward
            let perfect = (post_residual - next_item_size) as f64;
            score -= 30.0 - perfect.min(30.0) * 0.3;
        } else {
            // next item does not fit; penalize proportionally to wasted lookahead opportunity
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
        // Relative coupling to mean residual: bins far from mean residual are less flexible
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    } else {
        // Last item: pure best-fit
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // Opening new bin is only good if the item is huge relative to capacity
        // or no open bin gives a good fit; base cost:
        score += 20.0;
        if item_size >= 70 {
            score -= 15.0; // big items deserve fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 20.0; // item + next likely fill a fresh bin
        }
    }

    // Penalize creating very small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference for filling bins tighter than mean residual (consolidation)
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Early in the stream, allow more bins for flexibility; late, pack tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_bonus = 12.0 + 0.25 * (next_item_size as f64);
        score -= chain_bonus * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    } else if next_item_size > 0 {
        // Post-residual can't host next item: penalize proportionally to how
        // "dead" the leftover space is relative to the smallest plausible item.
        let deadness = post_residual as f64 / (next_item_size as f64).max(1.0);
        if deadness < 1.0 {
            score += 6.0 * (1.0 - deadness);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // (high mean residual spread) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        let mut new_bin_score = 30.0 + 0.6 * mean_residual;
        // Early on, prefer packing into existing bins unless they're very fragmented.
        new_bin_score -= 25.0 * progress;
        new_bin_score += 10.0 * fragmentation;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            new_bin_score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
        score = new_bin_score;
    } else {
        // Mild penalty for leaving residual far from mean (keeps pool homogeneous).
        score += 0.08 * ((post_residual as f64 - mean_residual).abs());
    }

    // Time-horizon modulation: late in the stream, squeeze harder (favor tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty on very large post-residuals (wasted space hoarding).
    if post_residual > bin_capacity / 2 {
        score += 0.05 * (post_residual as f64 - bin_capacity as f64 / 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear penalty on mid-range waste
    let mut score = pr as f64;

    // Smooth quartic dead-space term: penalize residuals near half-capacity (hard to fill)
    let x = norm_pr;
    score += 8.0 * (x - 0.5) * (x - 0.5) * (x - 0.5) * (x - 0.5) * cap;

    // Non-linear coupling with stream progress: early on, prefer tight fills;
    // later, be more tolerant of residual to keep bins consolidated
    let tight_fit = 1.0 - (norm_pr * 2.0 - 1.0) * (norm_pr * 2.0 - 1.0); // peaks at pr=50
    score -= (1.0 - progress) * 6.0 * tight_fit * (item_size as f64 / cap);
    score += progress * 2.0 * norm_pr * (open_bins_count as f64).ln();

    // Lookahead coupling: smooth reward if next item fits the post residual
    if next_item_size > 0 {
        let fits = ((pr - next_item_size as f64).abs() < 0.5) as f64;
        let near_fit = (-((pr - next_item_size as f64) / cap).powi(2) * 4.0).exp();
        score -= 5.0 * fits + 3.0 * near_fit * (1.0 - progress);
    }

    // Last-chance bonus: smooth sigmoid on fitting_bins_count == 1
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.5f64).exp() * 4.0);
    score -= 7.0 * last_chance;

    // Mean-residual divergence: prefer bins whose residual differs from mean
    // to diversify residual spectrum (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * (0.5 + progress);

    // Mild consolidation pressure as open bins grow
    score += 0.8 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers in the same residue class
    // (mod 10) are more likely to be filled by future items of matching class.
    let post_class = post_residual % 10;
    let item_class = item_size % 10;
    let next_class = next_item_size % 10;

    // Reward leftovers whose class matches the next item's class (they can pair).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            if post_class == next_class {
                score -= 12.0;
            } else if post_class.wrapping_add(next_class) == 10 {
                score -= 9.0;
            }
        } else {
            // Next item cannot use this bin's leftover at all: penalize dead space.
            score += 8.0 + (next_item_size as f64) * 0.05;
        }
    }

    // Integer-division thresholds on post_residual: very small leftovers are dead space.
    if post_residual <= 10 {
        score += 15.0;
    } else if post_residual <= 20 {
        score += 6.0;
    } else if post_residual <= 30 {
        score -= 3.0;
    } else if post_residual <= 50 {
        score -= 6.0;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it to
    // avoid opening a new bin, scaled by how tight the fit is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
