    // the penalty when no open bin fits well (avoid forcing bad fits).
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else if fitting_bins_count <= 2 {
            // Few options: opening a fresh bin may still be reasonable
            // if the best existing fit would leave a lot of waste.
            score -= 10.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Large items justify a fresh bin more than tiny ones.
        if item_size as f64 > 0.6 * cap {
            score -= 5.0;
        }
    }

    // Slight preference for filling large items into tight bins.
    score += 0.05 * item_size as f64 * (post_residual as f64 / cap);

    // Global waste pressure: encourage near-perfect closures.
    if post_residual == 0 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Next item fits in the post residual: reward scaled by tightness of the fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
    }
    // Post residual too small for next item: penalize dead space, worse if tiny.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste_ratio = post_residual as f64 / next_item_size as f64;
        // Dead space that is nearly the size of the next item is worst.
        score += 12.0 + 18.0 * (1.0 - waste_ratio);
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Exact fill is ideal regardless of anything else.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Near-exact fill: reward bins whose post residual is very small.
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate logic: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 18.0;
        if fitting_bins_count == 0 {
            // No alternative: new bin is necessary, remove penalty.
            score -= 40.0;
        } else if fitting_bins_count <= 2 {
            // Few alternatives: soften the penalty slightly so a fresh bin
            // can win over a very poor fit.
            score -= 12.0;
        }
        // If the current item is large relative to mean residual of open bins,
        // opening a fresh bin is more acceptable.
        let avg_open_residual = mean_residual.max(1.0);
        if item_size as f64 > 0.8 * avg_open_residual {
            score -= 6.0;
        }
        // Late in the stream, opening new bins wastes capacity; penalize more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
    }

    // Lookahead pair heuristic: if item + next item exactly fills the bin,
    // this is a perfect pairing — reward heavily.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 35.0;
    }

    // Slight preference for filling large items into tight bins.
    score += 0.06 * item_size as f64 * (post_residual as f64 / cap);

    // Prefer bins whose residual is a multiple-friendly remainder for typical
    // small items: mild reward when post_residual is in a common small-item band.
    if post_residual >= 1 && post_residual <= 25 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: very strong reward.
    if post_residual == 0 {
        score -= 140.0;
    } else if post_residual < 10 {
        score += 55.0 + (10 - post_residual as i32) as f64 * 4.0;
    }

    // Reward tight bins (high fill ratio).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Lookahead: exact 2-step match is gold; then next-item fits scaled by tightness.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space guaranteed; penalize worse when residual is tiny relative to next item.
            score += 18.0 + 18.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Compare against mean residual: prefer tighter-than-average bins.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless nothing fits anywhere.
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
        if mean_residual >= item_size as f64 {
            score += 35.0;
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Large items are hard to place later: allow a fresh bin for them.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        score += 0.5 * open_bins_count as f64;
        // Reward bins whose residual can still host the next item too.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Slight preference for placing large items into tight bins.
    score += 0.05 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}
